`timescale 1ns/1ps
module tb_debug_chain5h8; localparam W=32; localparam H=8; localparam B=80; reg clk=0; always #5 clk=~clk; reg rst_n=0,vs=1,de=0; reg [7:0] gray=0; wire mv; wire [7:0] mg,mc; median5x5_video #(.H_ACTIVE(W)) m(.clk(clk),.rst_n(rst_n),.hs_in(1'b1),.vs_in(vs),.de_in(de),.gray_in(gray),.hs_out(),.vs_out(),.de_out(mv),.gray_out(mg),.gray_center_out(mc)); wire [7:0] se,sg; wire [11:0] mag; wire [1:0] dir; wire sv; sobel_stream #(.H_ACTIVE(W)) s(.clk(clk),.rst_n(rst_n),.vsync_n(vs),.pixel_valid(mv),.gray_in(mg),.gray_center_in(mc),.edge_out(se),.magnitude_out(mag),.direction_out(dir),.window_valid_out(sv),.gray_center_out(sg)); wire [7:0] he,hg; wire hv; hysteresis_stream #(.H_ACTIVE(W-2)) h(.clk(clk),.rst_n(rst_n),.vsync_n(vs),.pixel_valid(sv),.magnitude_in(mag),.gray_in(sg),.low_threshold_in(12'd60),.high_threshold_in(12'd120),.edge_out(he),.gray_out(hg),.pixel_valid_out(hv)); reg [11:0] md1,md2; wire [7:0] ee,eg; edge_frame_hold #(.H_ACTIVE(W-2),.V_ACTIVE(H)) e(.clk(clk),.rst_n(rst_n),.vsync_n(vs),.pixel_valid(hv),.edge_in(he),.gray_in(hg),.magnitude_in(md2),.release_threshold_in(12'd30),.edge_out(ee),.gray_out(eg)); integer x,y,b,ce=0; always @(posedge clk) begin md1<=mag;md2<=md1; #1;if(eg!=0)begin ce=ce+1;$display("t=%0t gray=%0d edge=%0d mag=%0d de=%b y=%0d x=%0d",$time,eg,ee,mag,de,y,x);end end initial begin repeat(5)@(negedge clk);rst_n=1;vs=0;repeat(30)@(negedge clk);vs=1;for(y=0;y<H;y=y+1)begin for(x=0;x<W;x=x+1)begin de=1;gray=(y*32+x)*73;@(negedge clk);end de=0;gray=0;for(b=0;b<B;b=b+1)@(negedge clk);end repeat(100)@(negedge clk);$display("count=%0d",ce);$finish;end endmodule
